import { parseOpenGraph } from './openGraph';
import { networkConfig } from '../config/network';

export interface Preview {
  title: string;
  description: string;
  image: string | null;
}

export async function fetchPreview(target: string): Promise<Preview> {
  const response = await fetch(target, {
    redirect: 'follow',
    signal: AbortSignal.timeout(networkConfig.previewTimeoutMs),
  });

  const html = await response.text();
  return parseOpenGraph(html);
}

import { Router } from 'express';
import { requireAuth } from '../middleware/requireAuth';
import { fetchPreview } from '../services/preview.service';

export const previewRouter = Router();

previewRouter.post('/previews', requireAuth, async (req, res) => {
  const url = String(req.body?.url ?? '');

  if (!url.startsWith('http://') && !url.startsWith('https://')) {
    return res.status(400).json({ error: 'A preview needs an http or https URL' });
  }

  const preview = await fetchPreview(url);
  return res.json({ preview });
});

