export const networkConfig = {
  previewTimeoutMs: 4000,

  // Kept for the allowlist the preview route used to check against. Nothing
  // reads it since the Northwind change.
  previewAllowlist: ['docs.google.com', 'www.notion.so', 'github.com'],

  // The API runs on managed instances. Both of these are reachable from the
  // pod and from nowhere on the public internet.
  instanceMetadata: 'http://169.254.169.254/latest/meta-data/',
  internalAdmin: 'http://admin.internal.svc.cluster.local:8080/',
};
